    title: bossTemplate?.title ?? rng.pick(contentRegistry.enemyTitles),
    hp: maxHp,
    maxHp,
    power: Math.round((7 + difficulty * 1.25 + depth * 0.42) * (elite ? 1.15 : 1) * archetype.powerMultiplier),
    armor: Math.round(difficulty * 0.55 + depth * 0.3 + (elite ? 2 : 0)) + archetype.armorBonus,
    agility: 4 + Math.round(difficulty * 0.45 + rng.int(-1, 2)) + archetype.agilityBonus,
    damageType: archetype.id === "mystic" ? "mystic" : rng.pick(["slash", "crush", "pierce", "mystic"]),
    trait: trait[0],
    traitDescription: trait[1],
